with unpacked as (select id, plan, currency, tier_limits, tier_prices, discounts, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price from price_tiers) select *, lag(entry_price) over w_grp as prev_entry_price, lead(avg_tier_price) over w_grp as next_avg_tier_price, lag(avg_tier_price) over w_grp as prev_avg_tier_price, row_number() over w_grp as row_seq, ntile(3) over (partition by plan order by entry_price, id) as entry_price_bucket from unpacked where avg_tier_price < 21 window w_grp as (partition by plan order by avg_tier_price, id);
